contracts/Web3CashEscrow.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {EIP712} from "@openzeppelin/contracts/utils/cryptography/EIP712.sol";
import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title Web3CashEscrow
 * @notice Per-campaign USDC escrow that pays users via attestor-signed
 *         claim authorisations.
 *
 * @dev Lifecycle:
 *      1. Project creates a campaign via `createCampaign(...)` and pulls in
 *         USDC via ERC-20 `transferFrom` (escrow holds the funds).
 *      2. Web3Cash backend signs an EIP-712 `Claim` for each verified user
 *         completion: (campaignId, recipient, amount, claimId, deadline).
 *      3. The recipient (or any relayer) calls `claim(...)`. The escrow
 *         verifies the attestor sig, debits the campaign balance, and
 *         transfers USDC.
 *      4. Project may `withdrawRemaining(...)` after `endsAt` (or anytime
 *         while campaign is paused) to claw back unspent budget.
 *
 * Trust model:
 *   - `owner` (Web3Cash multisig) sets the global attestor and may pause.
 *   - `attestor` is the hot wallet that the backend uses to sign claims.
 *   - Each campaign has a `funder` who deposited and may reclaim.
 *   - `claimId` is enforced unique per campaign (one-shot).
 */
contract Web3CashEscrow is Ownable, EIP712, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    bytes32 public constant CLAIM_TYPEHASH =
        keccak256(
            "Claim(bytes32 campaignId,address recipient,uint256 amount,bytes32 claimId,uint256 deadline)"
        );

    /// Single ERC-20 token (USDC) this escrow handles. Set at construction.
    IERC20 public immutable token;

    /// Attestor key whose signatures authorise claims.
    address public attestor;

    struct Campaign {
        address funder;
        uint128 deposited;
        uint128 paid;
        uint64 endsAt; // 0 = no end
        bool exists;
    }

    /// campaignId => campaign state.
    mapping(bytes32 => Campaign) public campaigns;

    /// campaignId => claimId => used.
    mapping(bytes32 => mapping(bytes32 => bool)) public claimed;

    event AttestorRotated(address indexed previous, address indexed current);
    event CampaignCreated(
        bytes32 indexed campaignId,
        address indexed funder,
        uint256 amount,
        uint64 endsAt
    );
    event CampaignTopUp(
        bytes32 indexed campaignId,
        address indexed funder,
        uint256 amount
    );
    event Claimed(
        bytes32 indexed campaignId,
        address indexed recipient,
        bytes32 indexed claimId,
        uint256 amount
    );
    event Withdrawn(
        bytes32 indexed campaignId,
        address indexed to,
        uint256 amount
    );

    error InvalidAttestor();
    error CampaignAlreadyExists();
    error CampaignNotFound();
    error CampaignActive();
    error AlreadyClaimed();
    error ClaimExpired();
    error InvalidSignature();
    error InsufficientBalance();
    error NotFunder();
    error ZeroAmount();

    constructor(
        IERC20 token_,
        address initialOwner,
        address initialAttestor
    ) EIP712("Web3CashEscrow", "1") Ownable(initialOwner) {
        if (address(token_) == address(0)) revert InvalidAttestor();
        if (initialAttestor == address(0)) revert InvalidAttestor();
        token = token_;
        attestor = initialAttestor;
        emit AttestorRotated(address(0), initialAttestor);
    }

    function setAttestor(address newAttestor) external onlyOwner {
        if (newAttestor == address(0)) revert InvalidAttestor();
        emit AttestorRotated(attestor, newAttestor);
        attestor = newAttestor;
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @notice Create a new campaign and pull `amount` USDC from `msg.sender`.
     * @param campaignId Off-chain UUID hashed to bytes32 (e.g. keccak256(uuid)).
     * @param amount Initial budget in USDC atomic units (6 decimals).
     * @param endsAt Unix timestamp after which the funder can reclaim. 0 = open.
     */
    function createCampaign(
        bytes32 campaignId,
        uint256 amount,
        uint64 endsAt
    ) external nonReentrant whenNotPaused {
        if (campaigns[campaignId].exists) revert CampaignAlreadyExists();
        if (amount == 0) revert ZeroAmount();

        campaigns[campaignId] = Campaign({
            funder: msg.sender,
            deposited: _safe128(amount),
            paid: 0,
            endsAt: endsAt,
            exists: true
        });

        token.safeTransferFrom(msg.sender, address(this), amount);
        emit CampaignCreated(campaignId, msg.sender, amount, endsAt);
    }

    /// @notice Add more budget to an existing campaign. Anyone may top up.
    function topUp(
        bytes32 campaignId,
        uint256 amount
    ) external nonReentrant whenNotPaused {
        Campaign storage c = campaigns[campaignId];
        if (!c.exists) revert CampaignNotFound();
        if (amount == 0) revert ZeroAmount();

        c.deposited = _safe128(uint256(c.deposited) + amount);
        token.safeTransferFrom(msg.sender, address(this), amount);
        emit CampaignTopUp(campaignId, msg.sender, amount);
    }

    /**
     * @notice Settle a verified completion. Anyone may relay this.
     * @param signature EIP-712 signature from the current attestor over Claim.
     */
    function claim(
        bytes32 campaignId,
        address recipient,
        uint256 amount,
        bytes32 claimId,
        uint256 deadline,
        bytes calldata signature
    ) external nonReentrant whenNotPaused {
        if (block.timestamp > deadline) revert ClaimExpired();
        if (amount == 0) revert ZeroAmount();
        if (claimed[campaignId][claimId]) revert AlreadyClaimed();

        Campaign storage c = campaigns[campaignId];
        if (!c.exists) revert CampaignNotFound();
        if (uint256(c.deposited) - uint256(c.paid) < amount)
            revert InsufficientBalance();

        bytes32 structHash = keccak256(
            abi.encode(
                CLAIM_TYPEHASH,
                campaignId,
                recipient,
                amount,
                claimId,
                deadline
            )
        );
        bytes32 digest = _hashTypedDataV4(structHash);
        address recovered = ECDSA.recover(digest, signature);
        if (recovered != attestor) revert InvalidSignature();

        claimed[campaignId][claimId] = true;
        c.paid = _safe128(uint256(c.paid) + amount);

        token.safeTransfer(recipient, amount);
        emit Claimed(campaignId, recipient, claimId, amount);
    }

    /**
     * @notice Funder reclaims unspent budget. Allowed when:
     *           - campaign endsAt has passed, OR
     *           - the contract is paused (emergency).
     */
    function withdrawRemaining(
        bytes32 campaignId,
        address to
    ) external nonReentrant {
        Campaign storage c = campaigns[campaignId];
        if (!c.exists) revert CampaignNotFound();
        if (msg.sender != c.funder) revert NotFunder();

        bool ended = c.endsAt != 0 && block.timestamp >= c.endsAt;
        if (!ended && !paused()) revert CampaignActive();

        uint256 remaining = uint256(c.deposited) - uint256(c.paid);
        if (remaining == 0) revert ZeroAmount();

        c.paid = c.deposited; // fully drained
        token.safeTransfer(to, remaining);
        emit Withdrawn(campaignId, to, remaining);
    }

    /// @notice Remaining (unpaid) budget for a campaign.
    function remainingOf(bytes32 campaignId) external view returns (uint256) {
        Campaign storage c = campaigns[campaignId];
        if (!c.exists) return 0;
        return uint256(c.deposited) - uint256(c.paid);
    }

    function domainSeparator() external view returns (bytes32) {
        return _domainSeparatorV4();
    }

    function _safe128(uint256 v) private pure returns (uint128) {
        require(v <= type(uint128).max, "overflow");
        return uint128(v);
    }
}

contracts/Web3CashEscrowV2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";

/**
 * @title Web3CashEscrowV2
 * @notice Enhanced escrow with per-campaign balance tracking
 * @dev Supports both platform-funded and creator-funded campaigns
 */
contract Web3CashEscrowV2 is ReentrancyGuard, Ownable {
    using ECDSA for bytes32;

    IERC20 public immutable USDC;
    address public attestor;

    struct Campaign {
        address creator;
        uint256 balance;      // Funds deposited by creator
        uint256 spent;        // Funds paid out to users
        bool active;
    }

    mapping(bytes32 => Campaign) public campaigns;
    mapping(bytes32 => bool) public claimed;

    uint256 public platformReserve; // Platform's own funds for subsidizing

    event CampaignCreated(bytes32 indexed campaignId, address indexed creator);
    event CampaignFunded(bytes32 indexed campaignId, address indexed funder, uint256 amount);
    event Claimed(bytes32 indexed campaignId, address indexed recipient, uint256 amount, bytes32 claimId);
    event CampaignWithdrawn(bytes32 indexed campaignId, address indexed creator, uint256 amount);
    event PlatformReserveFunded(address indexed funder, uint256 amount);
    event CampaignDeactivated(bytes32 indexed campaignId);
    event AttestorUpdated(address indexed oldAttestor, address indexed newAttestor);

    error CampaignExists();
    error CampaignNotActive();
    error ZeroAmount();
    error ClaimExpired();
    error AlreadyClaimed();
    error InvalidSignature();
    error InsufficientFunds();
    error NotCreator();
    error InsufficientBalance();
    error CampaignNotFound();

    constructor(address _usdc, address _attestor) Ownable(msg.sender) {
        require(_usdc != address(0), "invalid USDC address");
        require(_attestor != address(0), "invalid attestor");
        USDC = IERC20(_usdc);
        attestor = _attestor;
    }

    /**
     * @notice Create a new campaign (free, no funds required)
     * @param campaignId Unique identifier for the campaign
     */
    function createCampaign(bytes32 campaignId) external {
        if (campaigns[campaignId].creator != address(0)) revert CampaignExists();

        campaigns[campaignId] = Campaign({
            creator: msg.sender,
            balance: 0,
            spent: 0,
            active: true
        });

        emit CampaignCreated(campaignId, msg.sender);
    }

    /**
     * @notice Fund a campaign (can be called multiple times)
     * @param campaignId Campaign to fund
     * @param amount Amount of USDC to deposit
     */
    function fundCampaign(bytes32 campaignId, uint256 amount) external nonReentrant {
        Campaign storage campaign = campaigns[campaignId];
        if (!campaign.active) revert CampaignNotActive();
        if (campaign.creator == address(0)) revert CampaignNotFound();
        if (amount == 0) revert ZeroAmount();

        require(USDC.transferFrom(msg.sender, address(this), amount), "transfer failed");
        campaign.balance += amount;

        emit CampaignFunded(campaignId, msg.sender, amount);
    }

    /**
     * @notice Platform can add funds to reserve for subsidizing campaigns
     * @param amount Amount of USDC to add to platform reserve
     */
    function fundPlatformReserve(uint256 amount) external nonReentrant {
        if (amount == 0) revert ZeroAmount();

        require(USDC.transferFrom(msg.sender, address(this), amount), "transfer failed");
        platformReserve += amount;

        emit PlatformReserveFunded(msg.sender, amount);
    }

    /**
     * @notice Claim reward (uses campaign balance first, then platform reserve)
     * @param campaignId Campaign the reward is from
     * @param recipient User receiving the reward
     * @param amount Amount of USDC to claim
     * @param claimId Unique claim identifier
     * @param deadline Claim expiration timestamp
     * @param signature Attestor's signature
     */
    function claim(
        bytes32 campaignId,
        address recipient,
        uint256 amount,
        bytes32 claimId,
        uint256 deadline,
        bytes calldata signature
    ) external nonReentrant {
        if (block.timestamp > deadline) revert ClaimExpired();
        if (claimed[claimId]) revert AlreadyClaimed();

        Campaign storage campaign = campaigns[campaignId];
        if (!campaign.active) revert CampaignNotActive();
        if (campaign.creator == address(0)) revert CampaignNotFound();

        // Verify attestor signature
        bytes32 messageHash = keccak256(
            abi.encodePacked(campaignId, recipient, amount, claimId, deadline)
        );
        bytes32 ethSignedMessageHash = MessageHashUtils.toEthSignedMessageHash(messageHash);
        address signer = ECDSA.recover(ethSignedMessageHash, signature);

        if (signer != attestor) revert InvalidSignature();

        // Try to use campaign balance first
        if (campaign.balance >= amount) {
            campaign.balance -= amount;
        } else {
            // Use platform reserve to cover shortfall
            uint256 shortfall = amount - campaign.balance;
            if (platformReserve < shortfall) revert InsufficientFunds();

            platformReserve -= shortfall;
            campaign.balance = 0;
        }

        campaign.spent += amount;
        claimed[claimId] = true;

        require(USDC.transfer(recipient, amount), "transfer failed");

        emit Claimed(campaignId, recipient, amount, claimId);
    }

    /**
     * @notice Campaign creator can withdraw unused funds
     * @param campaignId Campaign to withdraw from
     * @param amount Amount to withdraw
     */
    function withdrawCampaignFunds(bytes32 campaignId, uint256 amount) external nonReentrant {
        Campaign storage campaign = campaigns[campaignId];
        if (msg.sender != campaign.creator) revert NotCreator();
        if (campaign.balance < amount) revert InsufficientBalance();

        campaign.balance -= amount;
        require(USDC.transfer(msg.sender, amount), "transfer failed");

        emit CampaignWithdrawn(campaignId, msg.sender, amount);
    }

    /**
     * @notice Deactivate campaign (prevents new claims)
     * @param campaignId Campaign to deactivate
     */
    function deactivateCampaign(bytes32 campaignId) external {
        Campaign storage campaign = campaigns[campaignId];
        if (msg.sender != campaign.creator) revert NotCreator();

        campaign.active = false;
        emit CampaignDeactivated(campaignId);
    }

    /**
     * @notice Update attestor address (owner only)
     * @param _attestor New attestor address
     */
    function setAttestor(address _attestor) external onlyOwner {
        require(_attestor != address(0), "invalid attestor");
        address oldAttestor = attestor;
        attestor = _attestor;
        emit AttestorUpdated(oldAttestor, _attestor);
    }

    /**
     * @notice Get campaign details
     * @param campaignId Campaign identifier
     * @return creator Campaign creator address
     * @return balance Current campaign balance
     * @return spent Total amount spent from campaign
     * @return active Whether campaign is active
     */
    function getCampaign(bytes32 campaignId) 
        external 
        view 
        returns (
            address creator,
            uint256 balance,
            uint256 spent,
            bool active
        ) 
    {
        Campaign storage campaign = campaigns[campaignId];
        return (
            campaign.creator,
            campaign.balance,
            campaign.spent,
            campaign.active
        );
    }

    /**
     * @notice Get total available funds for a campaign (campaign balance + platform reserve)
     * @param campaignId Campaign identifier
     * @return Total available funds
     */
    function getAvailableFunds(bytes32 campaignId) external view returns (uint256) {
        Campaign storage campaign = campaigns[campaignId];
        return campaign.balance + platformReserve;
    }

    /**
     * @notice Emergency withdraw for owner (use with caution)
     * @param amount Amount to withdraw
     */
    function emergencyWithdraw(uint256 amount) external onlyOwner {
        require(USDC.transfer(msg.sender, amount), "transfer failed");
    }
}

contracts/Web3CashRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {EIP712} from "@openzeppelin/contracts/utils/cryptography/EIP712.sol";
import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

/**
 * @title Web3CashRegistry
 * @notice Append-only mapping of (wallet, platform) -> handleHash, gated by a
 *         trusted off-chain attestor (the Web3Cash backend).
 *
 * @dev Why on-chain?
 *      Phase 6 surfaces wallet ↔ social bindings to other dApps so they can
 *      Sybil-gate without re-running OAuth. The mapping is immutable per
 *      (wallet, platform) pair to prevent re-targeting attacks.
 *
 * Trust model:
 *   - Only an `attestor` signature is accepted. The attestor is rotated by the
 *     `owner` (Web3Cash multisig). Any user can submit a binding so long as it
 *     carries the attestor's EIP-712 signature, which removes the platform
 *     from the broadcast hot path.
 *   - The attestor signs `Bind(wallet, platform, handleHash, nonce, deadline)`
 *     where:
 *       - `platform` is keccak256("TWITTER") | keccak256("DISCORD") | ...
 *       - `handleHash` is keccak256(bytes(handle)) — a privacy-preserving
 *         commitment, not the raw username.
 *       - `nonce` is per-wallet to prevent replay across platforms.
 *       - `deadline` bounds signature validity.
 */
contract Web3CashRegistry is Ownable, EIP712 {
    bytes32 public constant BIND_TYPEHASH =
        keccak256(
            "Bind(address wallet,bytes32 platform,bytes32 handleHash,uint256 nonce,uint256 deadline)"
        );

    /// Active attestor — the only key whose signatures we accept on `bind`.
    address public attestor;

    /// wallet => platform => handleHash. Zero means "not bound".
    mapping(address => mapping(bytes32 => bytes32)) private _bindings;

    /// wallet => next valid bind nonce.
    mapping(address => uint256) public nonces;

    event AttestorRotated(address indexed previous, address indexed current);
    event Bound(
        address indexed wallet,
        bytes32 indexed platform,
        bytes32 handleHash,
        uint256 nonce
